diff --git a/test/anthropic-sdk1.test.js b/test/anthropic-sdk1.test.js
new file mode 100644
index 0000000..46aa20c
--- /dev/null
+++ b/test/anthropic-sdk1.test.js
@@ -0,0 +1,40 @@
+// Proof: aiHandler's Anthropic call goes out at 2026-10-21 with no sampling params.
+const assert = require('assert');
+const Module = require('module');
+const path = require('path');
+
+(async () => {
+  const captured = [];
+  const fakeFetch = async (url, init) => {
+    captured.push({ headers: new Headers(init.headers), body: JSON.parse(String(init.body)) });
+    return new Response(JSON.stringify({
+      id: 'm', type: 'message', role: 'assistant', model: 'x',
+      content: [{ type: 'text', text: 'hello' }], stop_reason: 'end_turn',
+      usage: { input_tokens: 1, output_tokens: 1 }
+    }), { headers: { 'content-type': 'application/json' } });
+  };
+
+  // Inject the stub fetch into the Anthropic client that aiHandler constructs.
+  const sdkPath = require.resolve('@anthropic-ai/sdk');
+  const Real = require(sdkPath);
+  const Ctor = Real.default || Real;
+  class Stubbed extends Ctor { constructor(o) { super({ ...o, fetch: fakeFetch }); } }
+  Stubbed.default = Stubbed; Stubbed.Anthropic = Stubbed;
+  const origLoad = Module._load;
+  Module._load = function (req, ...rest) {
+    if (req === '@anthropic-ai/sdk') return Stubbed;
+    return origLoad.call(this, req, ...rest);
+  };
+  const ai = require(path.join(__dirname, '..', 'aiHandler.js'));
+  Module._load = origLoad;
+
+  ai.initAI(null, 'dummy');
+  const out = await ai.generateResponse(
+    'what is the slab thickness?', async () => ({ chunks: [], visualFindings: [] }),
+    1, [], 'P', 'claude-sonnet-4', { useMultiQuery: false, useQueryDecomposition: false });
+  assert(JSON.stringify(out).includes('hello'), JSON.stringify(out));
+  assert.strictEqual(captured.length, 1);
+  assert.strictEqual(captured[0].headers.get('anthropic-version'), '2026-10-21');
+  for (const k of ['temperature', 'top_p', 'top_k']) assert(!(k in captured[0].body), k);
+  console.log('ok');
+})().catch(e => { console.error(e); process.exit(1); });
